import { createHash } from 'node:crypto';
import { readdir, readFile, writeFile } from 'node:fs/promises';
// Only files generated by this build enter the offline cache.
const files = (await readdir('dist', { recursive: true, withFileTypes: true }))
  .filter((f) => f.isFile() && !f.name.startsWith('.') && !f.parentPath.includes('/.vite'))
  .map((f) => (f.parentPath + '/' + f.name).slice(4))
  .filter((p) => p != '/sw.js')
  .sort();
const hash = createHash('sha256');
for (const file of files) hash.update(await readFile('dist' + file));
const cache = 'biteradar-assets-' + hash.digest('hex').slice(0, 16);
await writeFile(
  'dist/sw.js',
  [
    'const name=' + JSON.stringify(cache) + ';',
    'const files=' + JSON.stringify(files) + ';',
    "self.addEventListener('install',e=>e.waitUntil(caches.open(name).then(c=>c.addAll(files))));",
    "self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('biteradar-assets-') && k!==name).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));",
    "self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||u.search)return;const key=u.pathname.endsWith('/')?u.pathname+'index.html':u.pathname;if(files.includes(key))e.respondWith(caches.open(name).then(c=>c.match(key)).then(hit=>hit||fetch(e.request)));});"
  ].join('\n')
);
